import { tales } from './tales.js';

export const findStory = (id) =>
  stories.find((s) => s.id === id) || tales.find((t) => t.id === id) || null;

export const isProphetStory = (story) => story && Object.prototype.hasOwnProperty.call(story, 'honorific');
